// Bubble Sort implementation
vector<string> bubbleSort(vector<string> cards, bool& stable) {
    int n = cards.size();
    stable = true;

    for (int i = 0; i < n; i++) {
        for (int j = n - 1; j > i; j--) {
            if (getValue(cards[j]) < getValue(cards[j - 1])) {
                swap(cards[j], cards[j - 1]);
                stable = false;
            }
        }
    }
    return cards;
}

// Selection Sort implementation
vector<string> selectionSort(vector<string> cards, bool& stable) {
    int n = cards.size();
    stable = true;
    vector<int> originalPositions(n);
    for (int i = 0; i < n; i++) {
        originalPositions[i] = i;
    }

    for (int i = 0; i < n; i++) {
        int minj = i;
        for (int j = i; j < n; j++) {
            if (getValue(cards[j]) < getValue(cards[minj])) {
                minj = j;
            }
        }
        if (i != minj) {
            // Check if swapping would affect stability
            // If there are equal values between i and minj, stability is broken
            for (int k = i; k < minj; k++) {
                if (getValue(cards[k]) == getValue(cards[minj])) {
                    stable = false;
                    break;
                }
            }
            swap(cards[i], cards[minj]);
            swap(originalPositions[i], originalPositions[minj]);
        }
    }
    return cards;
}

