    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        String[] cards = new String[n];
        for (int i = 0; i < n; i++) {
            cards[i] = sc.next();
        }

        // Bubble Sort
        String[] bubble = Arrays.copyOf(cards, n);
        for (int i = 0; i < n; i++) {
            for (int j = n - 1; j > i; j--) {
                if (getValue(bubble[j]) < getValue(bubble[j-1])) {
                    String tmp = bubble[j];
                    bubble[j] = bubble[j-1];
                    bubble[j-1] = tmp;
                }
            }
        }

        // Selection Sort
        String[] selection = Arrays.copyOf(cards, n);
        for (int i = 0; i < n; i++) {
            int minIdx = i;
            for (int j = i + 1; j < n; j++) {
                if (getValue(selection[j]) < getValue(selection[minIdx])) {
                    minIdx = j;
                }
            }
            String tmp = selection[i];
            selection[i] = selection[minIdx];
            selection[minIdx] = tmp;
        }

        // Print bubble sort result
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            if (i > 0) sb.append(" ");
            sb.append(bubble[i]);
        }
        System.out.println(sb.toString());
        System.out.println(isStable(cards, bubble) ? "Stable" : "Not stable");

        // Print selection sort result
        sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            if (i > 0) sb.append(" ");
            sb.append(selection[i]);
        }
        System.out.println(sb.toString());
        System.out.println(isStable(cards, selection) ? "Stable" : "Not stable");
    }

    static int getValue(String card) {
        return card.charAt(1) - '0';
    }

    static boolean isStable(String[] original, String[] sorted) {
        int n = original.length;
        // For each pair of cards with same value in sorted array,
        // check if their relative order matches original
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (getValue(sorted[i]) == getValue(sorted[j])) {
                    // Find positions of sorted[i] and sorted[j] in original
                    // Need to be careful about duplicates - use index tracking
                    int posI = findPos(original, sorted[i], sorted, i);
                    int posJ = findPos(original, sorted[j], sorted, j);
                    if (posI > posJ) return false;
                }
            }
        }
        return true;
    }

    static int findPos(String[] original, String card, String[] sorted, int sortedIdx) {
        // Count how many times this card appears before sortedIdx in sorted
        int count = 0;
        for (int i = 0; i < sortedIdx; i++) {
            if (sorted[i].equals(card)) count++;
        }
        // Find the (count+1)-th occurrence in original
        int found = 0;
        for (int i = 0; i < original.length; i++) {
            if (original[i].equals(card)) {
                if (found == count) return i;
                found++;
            }
        }
        return -1;
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class Card {
        char suit;
        int value;
        int index; // original position

        Card(char suit, int value, int index) {
            this.suit = suit;
            this.value = value;
            this.index = index;
        }

        @Override
        public String toString() {
            return "" + suit + value;
        }
    }

    static void bubbleSort(Card[] a) {
        int n = a.length;
        for (int i = 0; i < n; i++) {
            for (int j = n - 1; j >= i + 1; j--) {
                if (a[j].value < a[j - 1].value) {
                    Card tmp = a[j];
                    a[j] = a[j - 1];
                    a[j - 1] = tmp;
                }
            }
        }
    }

    static void selectionSort(Card[] a) {
        int n = a.length;
        for (int i = 0; i < n; i++) {
            int minj = i;
            for (int j = i; j < n; j++) {
                if (a[j].value < a[minj].value) {
                    minj = j;
                }
            }
            Card tmp = a[i];
            a[i] = a[minj];
            a[minj] = tmp;
        }
    }

    static boolean isStable(Card[] sorted) {
        for (int i = 0; i < sorted.length; i++) {
            for (int j = i + 1; j < sorted.length; j++) {
                if (sorted[i].value == sorted[j].value && sorted[i].index > sorted[j].index) {
                    return false;
                }
            }
        }
        return true;
    }

    static Card[] copyCards(Card[] src) {
        Card[] res = new Card[src.length];
        for (int i = 0; i < src.length; i++) {
            res[i] = new Card(src[i].suit, src[i].value, src[i].index);
        }
        return res;
    }

    static void printCards(Card[] a, PrintWriter out) {
        for (int i = 0; i < a.length; i++) {
            if (i > 0) out.print(" ");
            out.print(a[i]);
        }
        out.println();
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);

        int n = Integer.parseInt(br.readLine().trim());
        StringTokenizer st = new StringTokenizer(br.readLine());

        Card[] cards = new Card[n];
        for (int i = 0; i < n; i++) {
            String s = st.nextToken();
            cards[i] = new Card(s.charAt(0), s.charAt(1) - '0', i);
        }

        Card[] bubble = copyCards(cards);
        Card[] selection = copyCards(cards);

        bubbleSort(bubble);
        selectionSort(selection);

        printCards(bubble, out);
        out.println(isStable(bubble) ? "Stable" : "Not stable");

        printCards(selection, out);
        out.println(isStable(selection) ? "Stable" : "Not stable");

        out.flush();
    }
}
